 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # The repeated multi-cell object is the stamp; isolated non-background cells are targets.
    runs = []
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < w and row[c] != bg:
                c += 1
            if c - start >= 2:
                runs.append((r, start, row[start:c]))
    if not runs:
        return [row[:] for row in grid]
    # Use the longest contiguous object as the template and preserve its original instance.
    tr, tc, pattern = max(runs, key=lambda item: len(item[2]))
    out = [row[:] for row in grid]
    targets = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row)
               if v != bg and not (r == tr and tc <= c < tc + len(pattern))]
    for r, c in targets:
        start = c - 2
        for i, value in enumerate(pattern):
            if 0 <= start + i < w:
                out[r][start + i] = value
        out[r][c] = bg
    return out
